package com.gamergaming.taczweaponblueprints.research.designer;

import static org.junit.jupiter.api.Assertions.*;
import java.util.*;
import com.google.gson.*;
import org.junit.jupiter.api.Test;
import com.gamergaming.taczweaponblueprints.resource.research.*;
import com.gamergaming.taczweaponblueprints.progression.*;
import com.gamergaming.taczweaponblueprints.progression.currency.ResearchCurrencyPolicy;
import net.minecraft.resources.ResourceLocation;

class DesignerPropertiesSimulationTest {
    record Fixture(ResearchDesignerProject project,DesignerCapturedContext context,ResearchDesignerCompiler.Candidate candidate){}
    Fixture fixture(String name){return fixture(name,false);}
    Fixture fixture(String name,boolean creativeBypass){return fixture(name,creativeBypass,true);}
    Fixture fixture(String name,boolean creativeBypass,boolean discoveryTracking){
        var f=ResearchDesignerContractTest.named(name);var original=ResearchDesignerContractTest.compileFixture(ResearchDesignerContractTest.project(f),f);
        var config=new com.gamergaming.taczweaponblueprints.compat.fzzy_config.BlueprintConfig();
        var configJson=DesignerValues.evidence(config.progressionSnapshot()).getAsJsonObject();configJson.addProperty("creativeBypassesResearchCost",creativeBypass);configJson.addProperty("discoveryTrackingEnabled",discoveryTracking);var progressionConfig=(BlueprintProgressionConfigSnapshot)DesignerCapturedSettings.read(BlueprintProgressionConfigSnapshot.class,configJson);
        var policies=BlueprintProgressionPolicyResolver.resolve(original.snapshot(),original.catalog(),1,1,Map.of(),config.researchFeatureSnapshot());
        var settings=new JsonObject();var effective=new JsonObject();effective.add("progression",DesignerValues.evidence(progressionConfig));effective.add("features",DesignerValues.evidence(config.researchFeatureSnapshot()));settings.add("effective",effective);
        var dependencies=new JsonObject();dependencies.add("mods",new JsonObject());var facts=new JsonObject();facts.add("items",new JsonObject());facts.add("item_tags",new JsonObject());facts.getAsJsonObject("items").addProperty("taczweaponblueprints:scrap",64);facts.getAsJsonObject("items").addProperty("minecraft:iron_ingot",64);
        var data=DesignerCaptureAssembly.assemble(new DesignerCaptureAssembly.Inputs(original.snapshot(),original.catalog(),original.profile(),Map.of(),Map.of(),policies.policiesByProfile().get(original.profile()),Map.of()),progressionConfig,BlueprintAccessConfigSnapshot.EMPTY,s->false,settings,facts,dependencies,(kind,id)->"fixture");
        var revisions=new JsonObject();for(String key:List.of("catalog","research","automatic","config","access","tags"))revisions.addProperty(key,1);
        var capture=ResearchDesignerCapture.create(UUID.randomUUID(),revisions,data);var project=ResearchDesignerConversion.createCustom(capture,"simulation_test","Simulation").project();var context=new DesignerCapturedContext(capture);
        return new Fixture(project,context,DesignerResearchProperties.evaluate(project,context));
    }
    @Test void oneFieldEditPreservesAllOtherSelectedRuleFieldsAndUndo(){var f=fixture("single");var n=f.project.draft().nodes().get(0);var plan=DesignerResearchProperties.change(f.project,n.id(),DesignerResearchProperties.Field.RESEARCH,Optional.of(new JsonPrimitive(false)));var after=ResearchDesignerStructure.node(plan.result(),n.id());var expected=n.policy().json();expected.addProperty("research_enabled",false);assertEquals(expected,after.policy().json());assertEquals(n.requirements(),after.requirements());assertEquals(n.placement(),after.placement());var s=new ResearchDesignerSession(f.project);plan.commit(s);s.undo();assertEquals(f.project.json(),s.project().json());}
    @Test void removingBenchOverridePreservesOtherProgressionFields(){var f=fixture("single");var n=f.project.draft().nodes().get(0);var policy=n.policy().json();var progression=new JsonObject();progression.addProperty("research_tier","tier_2");progression.addProperty("fragment_threshold",7);policy.add("progression",progression);var p=ResearchDesignerEdits.apply(f.project,ResearchDesignerEdits.policy(n.id(),policy)).project();var result=DesignerResearchProperties.change(p,n.id(),DesignerResearchProperties.Field.BENCH,Optional.empty()).result();assertEquals(7,ResearchDesignerStructure.node(result,n.id()).policy().json().getAsJsonObject("progression").get("fragment_threshold").getAsInt());}
    @Test void invalidTypedValuesCannotEnterProject(){var f=fixture("single");String n=f.project.draft().nodes().get(0).id();assertThrows(RuntimeException.class,()->DesignerResearchProperties.change(f.project,n,DesignerResearchProperties.Field.BENCH,Optional.of(new JsonPrimitive("tier_4"))));assertThrows(RuntimeException.class,()->DesignerResearchProperties.change(f.project,n,DesignerResearchProperties.Field.COST,Optional.of(JsonParser.parseString("{\"points\":1.5}"))));}
    @Test void domainChangesOnlySelectedDomain(){var f=fixture("single");var plan=DesignerResearchProperties.domain(f.project,"ammo",false,false);var p=plan.result().draft().profile().definition().json();assertFalse(p.getAsJsonObject("domain_policies").getAsJsonObject("ammo").get("tree_enabled").getAsBoolean());assertEquals(f.project.draft().nodes(),plan.result().draft().nodes());assertNotNull(DesignerResearchProperties.evaluate(plan.result(),f.context));}
    @Test void emptyScenarioCannotPayAndDoesNotMutateProject(){var f=fixture("single");var n=f.project.draft().nodes().get(0);var id=ResourceLocation.parse(n.blueprintId().orElseThrow());var state=DesignerSimulation.State.empty(TreeResearchResultMode.DIRECT_LEARN);var r=DesignerSimulation.evaluate(f.candidate,f.context,state,Optional.of(id));assertFalse(r.ready());assertThrows(IllegalStateException.class,()->DesignerSimulation.unlock(r,ResearchCurrencyPolicy.physical(ResearchCurrencyPolicy.SCRAP,1)));assertTrue(state.learned().isEmpty());assertEquals(f.project.digest(),f.candidate.projectDigest());}
    @Test void disclosureProjectionMatchesSharedRuntimePreview(){var f=fixture("inclusive_or");var state=DesignerSimulation.State.empty(TreeResearchResultMode.DIRECT_LEARN);var result=DesignerSimulation.evaluate(f.candidate,f.context,state,Optional.empty());var k=new com.gamergaming.taczweaponblueprints.capabilities.PlayerRecipeData();var expected=ResearchDesignerPreview.evaluate(f.candidate,f.context.catalog(),new ResearchDesignerPreview.Scenario(DesignerCapturedSettings.progression(f.context.capture(),f.candidate.profile()),DesignerCapturedSettings.features(f.context.capture()),k,f.context::blocked,f.context::exempt,Optional.empty(),false));assertEquals(expected.tree(),result.evaluation().tree());}
    @Test void fullKnowledgeHasNoNewUnlockPayment(){var f=fixture("inclusive_or");var ids=f.context.catalog().keySet().stream().map(Object::toString).collect(java.util.stream.Collectors.toSet());var state=new DesignerSimulation.State(ids,ids,Set.of(),List.of(),0,3,false,TreeResearchResultMode.DIRECT_LEARN,List.of());var r=DesignerSimulation.evaluate(f.candidate,f.context,state,Optional.of(ResourceLocation.parse("designer_fixture:end")));assertFalse(r.ready());assertTrue(r.unlocks().isEmpty());}

    DesignerSimulation.State funded(Fixture f,TreeResearchResultMode mode,Set<String> learned){return new DesignerSimulation.State(learned,f.context.catalog().keySet().stream().map(Object::toString).collect(java.util.stream.Collectors.toSet()),Set.of(),List.of(new ResearchIngredientPlanner.SlotFact(ResearchCurrencyPolicy.SCRAP,64,Set.of())),0,3,false,mode,List.of());}
    @Test void inclusiveRouteSharesRootAndPaysOnlyChosenAlternative(){var f=fixture("inclusive_or");var s=funded(f,TreeResearchResultMode.DIRECT_LEARN,Set.of());var r=DesignerSimulation.evaluate(f.candidate,f.context,s,Optional.of(ResourceLocation.parse("designer_fixture:end")));assertTrue(r.ready(),r.checks().toString());assertEquals(14,r.quote().orElseThrow().pointCost());assertEquals(4,r.unlocks().size());assertEquals(1,r.unlocks().stream().filter(id->id.getPath().equals("root")).count());assertEquals(1,r.unlocks().stream().filter(id->Set.of("left","right").contains(id.getPath())).count());var after=DesignerSimulation.unlock(r,DesignerCapturedSettings.progression(f.context.capture(),f.candidate.profile()).currencyPolicy());assertEquals(50,after.inventory().get(0).count());assertEquals(4,after.learned().size());assertTrue(s.learned().isEmpty());}
    @Test void learnedSupportRetainsMissingAncestryInQuote(){var f=fixture("inclusive_or");var s=funded(f,TreeResearchResultMode.DIRECT_LEARN,Set.of("designer_fixture:left"));var r=DesignerSimulation.evaluate(f.candidate,f.context,s,Optional.of(ResourceLocation.parse("designer_fixture:end")));assertTrue(r.ready(),r.checks().toString());assertEquals(12,r.quote().orElseThrow().pointCost());assertTrue(r.unlocks().contains(ResourceLocation.parse("designer_fixture:root")));assertFalse(r.unlocks().contains(ResourceLocation.parse("designer_fixture:left")));}
    @Test void physicalResultsDoNotLearnOrPurchaseAncestry(){var f=fixture("inclusive_or");var s=funded(f,TreeResearchResultMode.CREATE_BLUEPRINT,Set.of());var blocked=DesignerSimulation.evaluate(f.candidate,f.context,s,Optional.of(ResourceLocation.parse("designer_fixture:end")));assertFalse(blocked.ready());var root=DesignerSimulation.evaluate(f.candidate,f.context,s,Optional.of(ResourceLocation.parse("designer_fixture:root")));assertTrue(root.ready(),root.checks().toString());var after=DesignerSimulation.unlock(root,DesignerCapturedSettings.progression(f.context.capture(),f.candidate.profile()).currencyPolicy());assertTrue(after.learned().isEmpty());assertEquals(List.of("designer_fixture:root"),after.outputs());assertEquals(62,after.inventory().get(0).count());}
    @Test void incompleteAllocationCannotBeSimulatedAsSuccessful(){var f=fixture("single");var n=f.project.draft().nodes().get(0);var cost=JsonParser.parseString("{\"points\":2,\"ingredients\":[{\"items\":[\"taczweaponblueprints:scrap\"],\"count\":2}]}");var project=DesignerResearchProperties.change(f.project,n.id(),DesignerResearchProperties.Field.COST,Optional.of(cost)).result();var candidate=DesignerResearchProperties.evaluate(project,f.context);var s=new DesignerSimulation.State(Set.of(),Set.of(n.blueprintId().orElseThrow()),Set.of(),List.of(new ResearchIngredientPlanner.SlotFact(ResearchCurrencyPolicy.SCRAP,3,Set.of())),0,3,false,TreeResearchResultMode.DIRECT_LEARN,List.of());var r=DesignerSimulation.evaluate(candidate,f.context,s,Optional.of(ResourceLocation.parse(n.blueprintId().orElseThrow())));assertFalse(r.ready());assertTrue(r.allocation().isEmpty());}
    @Test void hiddenPolicyIsAbsentFromSyntheticPlayerProjection(){var f=fixture("single");var n=f.project.draft().nodes().get(0);var p=DesignerResearchProperties.change(f.project,n.id(),DesignerResearchProperties.Field.VISIBILITY,Optional.of(new JsonPrimitive("hidden"))).result();var candidate=DesignerResearchProperties.evaluate(p,f.context);var r=DesignerSimulation.evaluate(candidate,f.context,DesignerSimulation.State.empty(TreeResearchResultMode.DIRECT_LEARN),Optional.empty());assertEquals(0,r.evaluation().tree().graph().nodes().size());assertEquals(0,r.evaluation().tree().graph().edges().size());}

    @Test void creativeCostBypassUsesResolvedPolicyAndDoesNotSpendInventory(){var f=fixture("single",true);var n=f.project.draft().nodes().get(0);var p=DesignerResearchProperties.change(f.project,n.id(),DesignerResearchProperties.Field.CREATIVE,Optional.of(new JsonPrimitive(true))).result();var candidate=DesignerResearchProperties.evaluate(p,f.context);var s=new DesignerSimulation.State(Set.of(),Set.of(n.blueprintId().orElseThrow()),Set.of(),List.of(),0,3,true,TreeResearchResultMode.DIRECT_LEARN,List.of());var r=DesignerSimulation.evaluate(candidate,f.context,s,Optional.of(ResourceLocation.parse(n.blueprintId().orElseThrow())));assertTrue(r.ready(),r.checks().toString());assertEquals(0,r.quote().orElseThrow().pointCost());assertTrue(r.quote().orElseThrow().costBypassed());}
    @Test void scenarioExemptionBlocksSyntheticPurchase(){var f=fixture("single");var id=f.context.catalog().keySet().iterator().next();var s=new DesignerSimulation.State(Set.of(),Set.of(),Set.of(id.toString()),List.of(),0,3,true,TreeResearchResultMode.DIRECT_LEARN,List.of());var r=DesignerSimulation.evaluate(f.candidate,f.context,s,Optional.of(id));assertFalse(r.ready());assertTrue(r.checks().stream().anyMatch(v->v.contains("exempt")));}
    @Test void insufficientBenchTierBlocksOtherwiseFundedResearch(){var f=fixture("single");var n=f.project.draft().nodes().get(0);var p=DesignerResearchProperties.change(f.project,n.id(),DesignerResearchProperties.Field.BENCH,Optional.of(new JsonPrimitive("tier_3"))).result();var candidate=DesignerResearchProperties.evaluate(p,f.context);var supplied=funded(f,TreeResearchResultMode.DIRECT_LEARN,Set.of());var s=new DesignerSimulation.State(supplied.learned(),supplied.discovered(),supplied.exempt(),supplied.inventory(),0,1,false,supplied.resultMode(),List.of());var r=DesignerSimulation.evaluate(candidate,f.context,s,Optional.of(ResourceLocation.parse(n.blueprintId().orElseThrow())));assertFalse(r.ready());assertTrue(r.checks().stream().anyMatch(v->v.contains("Research Bench 3")));}
    @Test void bankedAffordabilityStillRequiresMaterials(){var quote=new ResearchPathUnlockPlanner.RouteQuote(5,List.of(new ResearchIngredientPlanner.Requirement(List.of(ResourceLocation.parse("minecraft:iron_ingot")),Optional.empty(),2)),false);assertTrue(ResearchDesignerPreview.allocateQuote(quote,ResearchCurrencyPolicy.banked(100,1),4,List.of()).isEmpty());var partial=ResearchDesignerPreview.allocateQuote(quote,ResearchCurrencyPolicy.banked(100,1),5,List.of(new ResearchIngredientPlanner.SlotFact(ResourceLocation.parse("minecraft:iron_ingot"),1,Set.of())));assertFalse(partial.orElseThrow().complete());}
    @Test void physicalOutputRespectsDisabledDiscoveryTracking(){var f=fixture("single",false,false);var supplied=funded(f,TreeResearchResultMode.CREATE_BLUEPRINT,Set.of());var s=new DesignerSimulation.State(Set.of(),Set.of(),Set.of(),supplied.inventory(),0,3,false,TreeResearchResultMode.CREATE_BLUEPRINT,List.of());var r=DesignerSimulation.evaluate(f.candidate,f.context,s,Optional.of(f.context.catalog().keySet().iterator().next()));assertTrue(r.ready(),r.checks().toString());var after=DesignerSimulation.unlock(r,DesignerCapturedSettings.progression(f.context.capture(),f.candidate.profile()).currencyPolicy());assertEquals(1,after.outputs().size());assertTrue(after.discovered().isEmpty());assertTrue(after.learned().isEmpty());}
}
